using System.Text;

namespace LunaDR.Core.Ripping;

/// <summary>
/// Builds the CodecPrivate of a Matroska S_VOBSUB track: the header part of a VobSub .idx file, as text.
/// Players need the frame size and the 16-color palette; the palette comes from the title's PGC, which stores colors as YCrCb.
/// The text follows MakeMKV's block line for line (only the "generated by" line names this program).
/// </summary>
public static class VobSubHeader {
	public static string Build(int width, int height, IReadOnlyList<uint> pgcPalette, string appName) {
		var sb = new StringBuilder();
		sb.Append("# VobSub index file, v7 (do not modify this line!)\n");
		sb.Append("# \n");
		sb.Append($"# This index block was generated by {appName}\n");
		sb.Append("# which has no relation to VobSub software. The first\n");
		sb.Append("# line above is present for compatibility reasons.\n");
		sb.Append("# \n");
		sb.Append($"size: {width}x{height}\n");
		sb.Append("org: 0, 0\n");
		sb.Append("alpha: 100%\n");
		sb.Append("smooth: OFF\n");
		sb.Append("fadein/out: 50, 50\n");
		sb.Append("align: OFF at LEFT TOP\n");
		sb.Append("time offset: 0\n");
		sb.Append("forced subs: OFF\n");
		sb.Append("langidx: 0\n");
		sb.Append("palette: ");
		sb.Append(string.Join(", ", pgcPalette.Select(YCrCbToRgbHex)));
		sb.Append('\n');
		sb.Append("# \n");
		sb.Append("# end\n");
		return sb.ToString();
	}

	/// <summary>
	/// PGC palette entry 0x00YYCrCb → "rrggbb" with the ITU-R BT.601 studio-range conversion (Y 16..235), as MakeMKV does.
	/// Checked on the test disc: Y 16 → 000000, 128 → 828282, 176 → bababa, 235 → ffffff.
	/// </summary>
	public static string YCrCbToRgbHex(uint entry) {
		double y = 1.164 * (((entry >> 16) & 0xFF) - 16.0);
		double cr = ((entry >> 8) & 0xFF) - 128.0;
		double cb = (entry & 0xFF) - 128.0;
		int r = Clamp(y + 1.596 * cr);
		int g = Clamp(y - 0.813 * cr - 0.391 * cb);
		int b = Clamp(y + 2.018 * cb);
		return $"{r:x2}{g:x2}{b:x2}";
	}

	private static int Clamp(double v) => (int)Math.Clamp(Math.Round(v), 0, 255);
}
